  str_homeland_secret_msg_10208 = "Yo vi Pepi y Victoria en la vivienda el otro día. Parecían cercanos.",
  str_homeland_secret_msg_10209 = "Sariel compró unos cientos de pares de los mismos calcetines para poder reemplazarlos a tiempo cuando se rompan.",
  str_homeland_secret_msg_10210 = "Yo vi Sariel cocinando comida con agua negra el otro día...",
  str_homeland_secret_msg_10211 = "Sariel¡Los padres de solían ser nobles de Lumopolis!",
  str_homeland_secret_msg_10212 = "Desde entonces Eicy se mudó al dormitorio, se escuchan extraños gritos por la noche...",
  str_homeland_secret_msg_10213 = "Eicy parece ser Victoriala hija de Por eso ella escucha Victoria.",
  str_homeland_secret_msg_10214 = "Eicy podría hacer que todos siguieran su orden si se quitara el parche en el ojo.",
  str_homeland_secret_msg_10215 = "La palabra por ahí es que Eicy siempre visita al Navegante a altas horas de la noche...",
  str_homeland_secret_msg_10216 = "Hace pocos meses, Migard hizo todo lo posible para quedarse con el Navigator por un tiempo. Por eso sabe tanto sobre los caelestitas.",
  str_homeland_secret_msg_10217 = "¿Escuchaste ese espeluznante crujido? parece venir de Migardmascota de",
  str_homeland_secret_msg_10218 = "Migard una vez quiso remolcar el Soroz a Illumina y desmantelarlo.",
  str_homeland_secret_msg_10219 = "Migard parece querer convertir la vivienda en un laboratorio... Dios...",
  str_homeland_secret_msg_10220 = "Corax se lavó las manos durante toda una noche hace unos días. Que esta pasando...?",
  str_homeland_secret_msg_10221 = "Corax es en realidad un reparador. Él fue quien reparó el Coloso la última vez.",
  str_homeland_secret_msg_10222 = "CoraxSus manos están heladas... a diferencia de una persona viva.",
  str_homeland_secret_msg_10223 = "¡Benny es mucho mejor que Curo en una pelea!",
  str_homeland_secret_msg_10224 = "La puntuación de tiro de Curo es mucho más alta que la de Benny.",
  str_homeland_secret_msg_10225 = "Tanto Benny como Curo le propusieron matrimonio al Navegante hace unos días. Dijeron que el Navigator es su \"objetivo\"...",
  str_homeland_secret_msg_10226 = "Cuscuta no le gusta dormir en la cama, por lo que siempre duerme en la naturaleza.",
  str_homeland_secret_msg_10227 = "Qué raro que un gran jardinero como Cuscuta solo cultiva rosas negras...",
  str_homeland_secret_msg_10228 = "Cuscuta parece tener sentimientos especiales por el Navegante...",
  str_homeland_secret_msg_10229 = "Recoge las espinas en Areiael cuerpo de ella, y ella caería.",
  str_homeland_secret_msg_10230 = "AreiaLa espada mágica de 's habla. Dice que creció con Areia.",
  str_homeland_secret_msg_10231 = "Vi al Navegante llorando en Areia hace solo unos dias...",
  str_homeland_secret_msg_10232 = "SikareLa cajita de 's contiene pistas sobre el tesoro escondido de su familia...",
  str_homeland_secret_msg_10233 = "escuché eso Sikare ¡está casado! ¿¡Es eso cierto!?",
  str_homeland_secret_msg_10234 = "\"Bola de nieve\" parece ser el nombre del perro que Sikare solía guardar.",
  str_homeland_secret_msg_10235 = "Yo vi Beverly y Charon juntos discutiendo algo de drama!",
  str_homeland_secret_msg_10236 = "Hace unos días, vi al Navegante volando, montado en la lanza relámpago que Beverly ¡conjurado!",
  str_homeland_secret_msg_10237 = "CarleenLa lanza de 's parece estar hecha por Beverly.",
  str_homeland_secret_msg_10238 = "Constantine parece haber estado en Northland. Incluso sirvió a la reina Bethlehem como su guardaespaldas.",
  str_homeland_secret_msg_10239 = "Constantine en realidad no sabe cómo usar un arma. Por lo general, solo golpea a los enemigos con la culata del arma.",
  str_homeland_secret_msg_10240 = "Lester ha estado en muchos lugares, ¡incluso en el Lejano Oriente!",
  str_homeland_secret_msg_10241 = "Lester se refiere a todos como \"señor\", independientemente de su género o edad...",
  str_homeland_secret_msg_10242 = "escuché eso Lester planea retirarse de su trabajo actual y trabajar como gerente en el dormitorio.",
  str_homeland_secret_msg_10243 = "Sylva¡La mano de podría transformarse en una espada larga!",
  str_homeland_secret_msg_10244 = "Sylva puede transformar la madera en hierro.",
  str_homeland_secret_msg_10245 = "Ansia habla muy bajo. Por eso usa un altavoz.",
  str_homeland_secret_msg_10246 = "Ansia probablemente quería unirse a Rediesel Wrench, solo por su música o algo así.",
  str_homeland_secret_msg_10247 = "Realmente, Ansia tiene gran vista. Incluso puede ver el color del ojo de un pájaro desde lejos.",
  str_homeland_secret_msg_10248 = "Tessa es genial en el boxeo. ¡Fue la campeona de todo el año en Umbraton!",
  str_homeland_secret_msg_10249 = "Todo TessaLos dientes de son falsos. ¡Es por eso que ella no necesita rehuir los dulces!",
  str_homeland_secret_msg_10250 = "Yo vi Tessa y Smokey compras en la calle de Umbraton. Incluso tomaron una copa... Hmmm...",
  str_homeland_secret_msg_10251 = "Escuché que mientras Leah está alrededor, no habría escasez de agua fresca en el dormitorio.",
  str_homeland_secret_msg_10252 = "Hace unos días, vi flotar el Navigator hasta la cima de una colina cercana en Leah's burbuja!",
  str_homeland_secret_msg_10253 = "cualquier flor Leah ¡los toques florecerían al instante!",
  str_homeland_secret_msg_10254 = "Ultima vez, Novio pensamiento Alice era un conejito y la llevó al Palacio de Invierno.",
  str_homeland_secret_msg_10255 = "AliceSe dice que las dos muñecas de fueron recogidas en la naturaleza cuando ella estaba sonámbula una vez.",
  str_homeland_secret_msg_10256 = "Alice le encanta la comida picante. ¡Incluso puede respirar fuego después!",
  str_homeland_secret_msg_10257 = "La botella de agua en SinsaEl cinturón contiene agua fría y caliente para Eve.",
  str_homeland_secret_msg_10258 = "Sinsa hace un shish kabob asesino. La última vez incluso dijo que preferiría ser un vendedor de brochetas que un líder.",
  str_homeland_secret_msg_10259 = "Yo vi Sinsa inmovilizando al Navegador por última vez, murmurando algo como \"No puedes hacer esto\".",
  str_homeland_secret_msg_10260 = "he oído Eve una vez usó algo especial solo para el Navegante!",
  str_homeland_secret_msg_10261 = "Eve hace visitas a Seleucid a menudo últimamente, casi tratándolo como un gato grande.",
  str_homeland_secret_msg_10262 = "Eve parece ser capaz de levantar el Soroz solo con una mano.",
  str_homeland_secret_msg_10263 = "La última vez, vi Eve, Sinsa, y el Navegante haciendo un picnic juntos. Eve incluso dijo que son una \"familia\" o algo así...",
  str_homeland_secret_msg_10264 = "Yo vi Dawn donación Eve Flores el otro día. Ellos deben ser...",
  str_homeland_secret_msg_10265 = "La Garganta de los Ojos Rojos pertenece a Dawn, pero se lo dieron al Navegante, escuché.",
  str_homeland_secret_msg_10266 = "Dawn utilizado para elevar Eclipsites!",
  str_homeland_secret_msg_10267 = "Todos Taki podría tomar es una copa de vino.",
  str_homeland_secret_msg_10268 = "Taki solo vino a Umbraton porque perdió todo lo que poseía jugando en el Lejano Oriente.",
  str_homeland_secret_msg_10269 = "Taki's Odd Jobs no ha tenido ningún trabajo últimamente. ¡Pronto cerrará!",
  str_homeland_secret_msg_10270 = "Últimamente hay muchos más cristales rojos en el dormitorio. ¿Alguien ganó la lotería y comenzó a dejar piedras preciosas por ahí?",
  str_homeland_secret_msg_10271 = "Beryl fuí a ver Faust hace unos días. Se escucharon ruidos extraños provenientes de Faustla habitación...",
  str_homeland_secret_msg_10272 = "Corre el rumor de que Beryl solía ser un noble de Lumopolis. Huyó cuando su familia se metió en algún tipo de problema.",
  str_homeland_secret_msg_10273 = "Beryl¡Las lágrimas se convierten en rubíes!",
  str_homeland_secret_msg_10274 = "Smokey ¡Parece haber derrotado a una mantícora en el pasado! ¡Era una criatura legendaria!",
  str_homeland_secret_msg_10275 = "Smokey no parece sentir dolor en absoluto.",
  str_homeland_secret_msg_10276 = "Cuando Smokey llegó por primera vez a Umbraton, quemó toda una calle...",
  str_homeland_secret_msg_10277 = "Smokey posee cientos de pares de anteojos de sol y usa un par diferente cada día.",
  str_homeland_secret_msg_10278 = "¿Sabes de ese lagarto gigante en Rediesel Wrench? Fleur ¡lo creó!",
  str_homeland_secret_msg_10279 = "Fleur parece haber sido secuestrado por una mujer con un revólver y entregado a Rediesel Wrench.",
  str_homeland_secret_msg_10280 = "escuché eso Fleur solo se escapó porque fue acosado por su superior en Illumina.",
  str_homeland_secret_msg_10281 = "La palabra es que BonacieLa casa de ella fue destruida por ella misma.",
  str_homeland_secret_msg_10282 = "La última vez Bonacie actuó en el concierto, incluso la Soroz bailó con su música.",
  str_homeland_secret_msg_10283 = "a pesar de cuanto Bonacie le encanta la música, no sabe componer nada. Ella simplemente actúa como si supiera cómo conducir.",
  str_homeland_secret_msg_10284 = "Genevieve y Smokey Debe ser un par, ya que siempre están juntos.",
  str_homeland_secret_msg_10285 = "la ultima vez cuando Genevieve se emborrachó, escuché que ella \"le hizo algo\" al Navegante allí mismo en el dormitorio...",
  str_homeland_secret_msg_10286 = "escuché eso Genevieve convirtió a su doncella en un caballo. Por eso el caballo se llama \"Anna\"...",
  str_homeland_secret_msg_10287 = "Pasolo tiene una letra hermosa. Ella practica la escritura todos los días en el dormitorio. Por eso siempre tiene tantos papeles encima.",
  str_homeland_secret_msg_10288 = "Hace unos días, cuando el Navegante trató de decirle Pasolo una historia, ella se molestó y lloró...",
  str_homeland_secret_msg_10289 = "Desde entonces Pasolo vino al dormitorio, el piso nunca quedó limpio. ¡Siempre hay pedazos de papel en el suelo aquí o allá!",
  str_homeland_secret_msg_10290 = "Gram incluso puede emborracharse bebiendo refrescos.",
  str_homeland_secret_msg_10291 = "Gram parece ser el que cocinaba todas las comidas servidas en el dormitorio.",
  str_homeland_secret_msg_10292 = "Anoche escuché el ruido del motor de un auto retumbando. Gram ¡Debe haber sacado su coche a dar una vuelta!",
  str_homeland_secret_msg_10293 = "Revy no puede tener ninguna comida picante en absoluto. Ella lloró durante un día entero después de haber comido un Spicy Cake anteriormente.",
  str_homeland_secret_msg_10294 = "Revy llamó al Navegante una \"buena persona\" la última vez. Eso significa...",
  str_homeland_secret_msg_10295 = "RevyLa espada debe ser de madera. ¿De qué otra forma podría levantarlo?",
  str_homeland_secret_msg_10296 = "Escuché al Navegante y Allura Abrieron juntos una tienda de antigüedades en Umbraton, ¡vendiendo cosas de Caelestite a bajo precio!",
  str_homeland_secret_msg_10297 = "Allura parece haber invertido en el Courier Union!",
  str_homeland_secret_msg_10298 = "he oído Allura solo se mudó al dormitorio para ver si debería comprarlo.",
  str_homeland_secret_msg_10299 = "Paloma solía trabajar en el templo de Lumopolis. La echaron porque rompió una estatua o algo así.",
  str_homeland_secret_msg_10300 = "Pact y Paloma son hermanas perdidas!",
  str_homeland_secret_msg_10301 = "Paloma y Pittman son compañeros de clase. ¡En realidad se conocen!",
  str_homeland_secret_msg_10302 = "Precisamente el otro día, vi el Navigator dando vueltas en Naroxelciervo. La puso furiosa...",
  str_homeland_secret_msg_10303 = "Naroxel parece ser capaz de comunicarse con los árboles. Son sus ojos y oídos.",
  str_homeland_secret_msg_10304 = "Naroxel tiene mucho miedo al frío, por lo que nunca se acercará a Northland.",
  str_homeland_secret_msg_10305 = "Tweety es un experto en peleas de bolas de nieve! ¡Nadie en el dormitorio puede vencerla!",
  str_homeland_secret_msg_10306 = "Tweety posee una posada entera en el Lejano Oriente. ¡Ella es rica, como resulta!",
  str_homeland_secret_msg_10307 = "escuché eso Tweety una vez quiso construir un dormitorio de nieve para todos... Menos mal que no sucedió.",
  str_homeland_secret_msg_10308 = "BethelLa mascota de parece haberse comido toda la comida del dormitorio.",
  str_homeland_secret_msg_10309 = "Bethel es en realidad un escritor famoso en Umbraton!",
  str_homeland_secret_msg_10310 = "escuché eso Bethel es la hija de Istvan!",
  str_homeland_secret_msg_10311 = "Yo vi Luke dibujando el Navigator el otro día. Tenía toda su atención.",
  str_homeland_secret_msg_10312 = "Tan pronto como Luke se pone esa chaqueta suya, puede convertirse en mariposa y volar.",
  str_homeland_secret_msg_10313 = "Nunca intentes atrapar una mariposa. Luke enviará a los mercenarios para que se ocupen de ti.",
  str_homeland_secret_msg_10314 = "Pittman solía pelear en la Arena Subterránea con Tessa en Umbratón. Incluso fue una vez campeón.",
  str_homeland_secret_msg_10315 = "Pittman perdió su brazo ante los Eclipsites en Umbraton.",
  str_homeland_secret_msg_10316 = "Pittman es un lector de velocidad. Termina muchos archivos todos los días.",
  str_homeland_secret_msg_10317 = "Escuché que en Lumopolis, cada comida cuesta Hedy millones de Nightium!",
  str_homeland_secret_msg_10318 = "Precisamente el otro día, el Navegante tomó Hedy's mano por error... y fue severamente castigado por Pompeyo por ello.",
  str_homeland_secret_msg_10319 = "Hedy no parece contento con el dormitorio. Quería construir uno nuevo.",
  str_homeland_secret_msg_10320 = "Yo vi Cordy llorando a la Navegante hace unos días, y ella seguía pidiendo disculpas...",
  str_homeland_secret_msg_10321 = "A pesar de Cordy¡A su corta edad, es sheriff sénior en Illumina!",
  str_homeland_secret_msg_10322 = "alguien vio Cordy teniendo tres comidas tardías hace unos días.",
  str_homeland_secret_msg_10323 = "Escuché que Hachi y Gin planean comprar el Soroz. ¡Por eso están aquí!",
  str_homeland_secret_msg_10324 = "Nunca toques la barbilla de Hachi. Entrará en pánico.",
  str_homeland_secret_msg_10325 = "Gin no parece tener cola...",
  str_homeland_secret_msg_10326 = "NovioEl hogar de es una tribu salvaje en lo profundo de las montañas de Northland.",
  str_homeland_secret_msg_10327 = "Novio¡El personal de parece poder hablar!",
  str_homeland_secret_msg_10328 = "Reina BethlehemEl Palacio de Invierno de 's parece haber sido construido por Novio.",
  str_homeland_secret_msg_10329 = "Lola es en realidad un conejito de Northland convertido en auroriano.",
  str_homeland_secret_msg_10330 = "No toques la marca en Lola¡El cuello de ella, o ella te cazará!",
  str_homeland_secret_msg_10331 = "Pasé por la cocina la otra noche y vi Lola comiendo dormida...",
  str_homeland_secret_msg_10332 = "Desde entonces Siobhan se mudó al dormitorio, se pueden encontrar redes extrañas en el techo...",
  str_homeland_secret_msg_10333 = "Siobhan es en realidad una antigua ella misma. Por eso está tan interesada en las ruinas antiguas.",
  str_homeland_secret_msg_10334 = "no dejes Siobhan estar junto con Gronru. No podrán hacer nada si eso sucede.",
  str_homeland_secret_msg_10335 = "Erica no parece ser de esta tierra en absoluto. ¿Por qué otra razón hablaría de una manera tan extraña?",
  str_homeland_secret_msg_10336 = "Erica es en realidad un profeta. ¡Ella predijo muchas cosas que desde entonces se han hecho realidad!",
  str_homeland_secret_msg_10337 = "Erica hizo adivinación para el Navegante hace unos días, diciendo que el Navegante y Vice voluntad...",
  str_homeland_secret_msg_10338 = "La extraña tela Florine viste parece ser comprado en Illumina.",
  str_homeland_secret_msg_10339 = "Florine¡La espada de es en realidad un bastón de curación!",
  str_homeland_secret_msg_10340 = "Florine perdió su serpiente en el dormitorio...",
  str_homeland_secret_msg_10341 = "Ruby abrió un agujero en la pared del dormitorio mientras jugaba béisbol... ¡Casi derriba el dormitorio!",
  str_homeland_secret_msg_10342 = "Ruby Puede ser una exploradora ansiosa, pero no tiene sentido de la orientación.",
  str_homeland_secret_msg_10343 = "Ruby dijo que su hámster algún día salvará al mundo...",
  str_homeland_secret_msg_10344 = "escuché eso RubyEl hámster de es en realidad su ración de emergencia en tiempos de necesidad.",
  str_homeland_secret_msg_10345 = "Rouge en realidad es vegano. A ella solo le gusta el olor de la carne.",
  str_homeland_secret_msg_10346 = "Rouge Realmente no le temen a los fantasmas. Ella solo finge tener miedo por Rubypor amor",
  str_homeland_secret_msg_10347 = "Rouge solo necesita dormir una hora al día, por lo que finge estar durmiendo la mayor parte del tiempo.",
  str_homeland_secret_msg_10348 = "¡Hay fantasmas en el dormitorio! Rinne descubrió que era cierto tan pronto como llegó aquí!",
  str_homeland_secret_msg_10349 = "Rinne parece ser capaz de hacer adivinación en las relaciones románticas. la última vez, ella dijo Yao y Amemori voluntad...",
  str_homeland_secret_msg_10350 = "Si RinneKagura Bell suena solo, algo malo va a pasar.",
  str_homeland_secret_msg_10351 = "Rinne parece haber sido un practicante en algún lugar muy, muy lejano.",
  str_homeland_secret_msg_10352 = "escuché eso Kayano se ha mudado al dormitorio. ¿Alguien la ha visto alguna vez?",
  str_homeland_secret_msg_10353 = "Kayano no es una auroriana, ¿verdad? ¿Por qué otra razón tendría tanto miedo de otras personas?",
  str_homeland_secret_msg_10354 = "Kayano no camina Ella flota alrededor.",
  str_homeland_secret_msg_10355 = "Amemori necesita dormir más de 16 horas al día, pero está igual de atenta incluso cuando duerme.",
  str_homeland_secret_msg_10356 = "Amemori odia el ajo!",
  str_homeland_secret_msg_10357 = "Amemori puede volverse invisible. ¡Todos, tengan cuidado en el dormitorio!",
  str_homeland_secret_msg_10358 = "Hace unos días, Yao casi se comió su almohada mientras dormía. De verdad, ¡lo vi!",
  str_homeland_secret_msg_10359 = "Yao no sabe nadar, pero puede flotar muy bien en el agua.",
  str_homeland_secret_msg_10360 = "Incluso cuando Yao ¡Era solo una niña, derrotó a miles de piratas!",
  str_homeland_secret_msg_10361 = "Yo vi Yao compartir con Vice un plato de \"tofu sin picante\" y luego...",
  str_homeland_secret_msg_10362 = "¡Momo aumentaría en secreto el total de los bienes comprados!",
  str_homeland_secret_msg_10363 = "¡Anzu siempre usa su dedo para probar la sopa que está cocinando!",
  str_homeland_secret_msg_10364 = "¡La tienda de ramen de Momo y Anzu abrirá una sucursal aquí!",
  str_homeland_secret_msg_10365 = "Tourdog¡El juego de hizo mucho dinero!",
  str_homeland_secret_msg_10366 = "Cuando está en modo de trabajo, Tourdog puede trabajar durante 25 horas al día!",
  str_homeland_secret_msg_10367 = "Algún noble en Lumopolis parece haber invertido en Tourdog...",
  str_homeland_secret_msg_10368 = "escuché eso Azure congelaría a las personas que le gustan!",
  str_homeland_secret_msg_10369 = "el borracho Azure obtiene, mejor conduce!",
  str_homeland_secret_msg_10370 = "Azure siempre lleva al navegador a dar un paseo, como si quisiera ser el entrenador del navegador.",
  str_homeland_secret_msg_10371 = "Azure parece haberle dado a su auto un nuevo apodo: Caelestite Cutie.",
  str_homeland_secret_msg_10372 = "Roy llama a sus abejas robot no solo \"Sweetie\" sino también \"Caelee\" y \"Azurie\"...",
  str_homeland_secret_msg_10373 = "La última vez que el sistema de Firefly falló, Roy acaba de patearlo...",
  str_homeland_secret_msg_10374 = "Una vez vi a Roy enseñarle a coser al Navegante. Nunca pensé que tuviera ese tipo de talento...",
  str_homeland_secret_msg_10375 = "La mochila del gatito de May tenía dos ojos originalmente. De alguna manera creció otro par...",
  str_homeland_secret_msg_10376 = "¡Quienquiera que hable con el gato blanco de May recibirá buena fortuna!",
  str_homeland_secret_msg_10377 = "La última vez, May le hizo al Navegante dos colas de caballo. ¡Fue adorable!",
  str_homeland_secret_msg_10378 = "Lenore no podrá moverse en absoluto si no se toca las orejas. Dijo que son sus \"resortes de tensión\".",
  str_homeland_secret_msg_10379 = "Justo el otro día, vi Lenore ¡sonriendo a la Navegante e invitando a la Navegante a su habitación!",
  str_homeland_secret_msg_10380 = "Si miras con atención, Lenore no parece tener un iris.",
  str_homeland_secret_msg_10381 = "Los cuernos en Giles' crece la cabeza. ¡Pueden crecer hasta dos pisos!",
  str_homeland_secret_msg_10382 = "Yo vi Giles criando cuervos en el dormitorio el otro día!",
  str_homeland_secret_msg_10383 = "Tan pronto como Giles se mudó, puede escuchar una voz espeluznante leyendo canciones infantiles por la noche en el dormitorio...",
  str_homeland_secret_msg_10384 = "Hace unos días, Reinhardt ni siquiera podía abrir una botella y tuvo que pedir ayuda al Navigator.",
  str_homeland_secret_msg_10385 = "Yo vi Reinhardt leyendo una novela romántica en secreto!",
  str_homeland_secret_msg_10386 = "¿Alguien vio esa vieja foto de Reinhardt ¿con pelo corto? ¡Ella era tan linda!",
  str_homeland_secret_msg_10387 = "Corre el rumor de que Reinhardt en realidad es un chico!",
  str_homeland_secret_msg_10388 = "Salen rayos de la muerte Vicelos ojos de !",
  str_homeland_secret_msg_10389 = "escuché eso Vice en realidad tiene una gemela que se ve exactamente como ella!",
  str_homeland_secret_msg_10390 = "Ahora eso Vice fue ascendida, ¡incluso cambió su guardarropa!",
  str_homeland_secret_msg_10391 = "escuché eso {1} me enfermé últimamente, hasta el brazo se puso raro...",
  str_homeland_secret_msg_10392 = "{1} estaba riendo como loco en el dormitorio el otro día, diciendo que el día para convertirse en el \"verdadero General de Illumina\" está cerca... Entonces, ¿quién es el General de Illumina en este momento?",
  str_homeland_secret_msg_10393 = "Yo vi {1} usando la espada de doble punta para pescar, ¡e incluso asó el pescado con ella!",
  str_homeland_secret_msg_10394 = "se dice que Vice una vez pensó que había perdido una horquilla solo para descubrir que la llevaba en la parte posterior de la cabeza.",
  str_homeland_secret_msg_10395 = "¡Se dice que la Sra. Blanc viaja con un juego de té lleno!",
  str_homeland_secret_msg_10396 = "se dice que Dove tiene todo un almacén lleno de paquetes en espera de entrega!",
  str_homeland_secret_msg_10397 = "¡Se dice que el arma de Rafael es tan pesada como una casa!",
  str_homeland_secret_msg_10398 = "Nikinis ajustaría la flor en su cabeza frente al espejo cuando nadie está mirando.",
  str_homeland_secret_msg_10399 = "se dice que Nina es un traficante de armas!",
  str_homeland_secret_msg_10400 = "Desde entonces Nina mudado, ¡todas las cortinas se han vuelto negras!",
  str_homeland_secret_msg_10401 = "se dice que Nina no le teme a los fantasmas en absoluto. ¡Ella realmente disfruta chateando con ellos!",
  str_homeland_secret_msg_10402 = "Nina ¡siempre tiene su sombrilla abierta incluso cuando está durmiendo!",
  str_homeland_secret_msg_10403 = "Sanae es un viajero de una tierra lejana.",
  str_homeland_secret_msg_10404 = "Sanae siempre habla sola... ¿Hablaría en su sueño?",
  str_homeland_secret_msg_10405 = "La habitación se siente tan llena de Sanae y su hermana mudándose...",
  str_homeland_secret_msg_10406 = "se dice que Carleen se convertirá en el Señor de la Ciudad de Lumopolis!",
  str_homeland_secret_msg_10407 = "¡Hace solo unas noches, los ojos de Carleen brillaban!",
  str_homeland_secret_msg_10408 = "¿Conoces el arma de Carleen? Está formado por Lumina y no tiene forma física.",
  str_homeland_secret_msg_10409 = "Carleen parece haber ganado una nueva habilidad. Escuché que puede controlar Lumopolis y hacer que vuele por todas partes.",
  str_homeland_secret_msg_10410 = "Ciel parecía haber hecho un mecha mientras dormía hace unos días.",
  str_homeland_secret_msg_10411 = "La armadura de la pierna de Ciel parece ser parte de su cuerpo. Nadie la ha visto quitárselo.",
  str_homeland_secret_msg_10412 = "¡Parece que Ciel es bueno pintando!",
  str_homeland_secret_msg_10413 = "¡Fia puede comunicarse con los animales!",
  str_homeland_secret_msg_10414 = "¡Se dice que este tipo, Kyllo, es la familia de Fia!",
  str_homeland_secret_msg_10415 = "Parece que Fia puede comunicarse con todo tipo de cosas, ¡incluso con esta casa!",
  str_homeland_secret_msg_10416 = "Desde que Fia se mudó, ha habido muchos artículos brillantes. ¿Podría ser que ella es una comerciante de gemas?",
  str_homeland_secret_msg_10417 = "La adivinación de Jeno siempre da en el blanco. ¡Pruébalo si no crees mis palabras!",
  str_homeland_secret_msg_10418 = "¡Las manos de Jeno son huecas y pueden esconder cosas adentro!",
  str_homeland_secret_msg_10419 = "Se dice que Jeno posee muchas cartas con diferentes patrones, ¡y cada carta representa un evento importante en el futuro!",
  str_homeland_secret_msg_10420 = "De hecho, Jeno no sabe nada de trucos de magia. Todo lo que hace es real.",
  str_homeland_secret_msg_10421 = "¡Rainbow me dijo que el barco tiene alma!",
  str_homeland_secret_msg_10422 = "¡Escuché a la gente decir que Rainbow es descendiente de la marina que huyó de Illumina!",
  str_homeland_secret_msg_10423 = "¡Rainbow tiene muchos amigos! Pero sus nombres son muy extraños: caña de pescar, tablas de madera, etc...",
  str_homeland_secret_msg_10424 = "¡Pólux es un ángel! Alguien vio una vez un halo sobre su cabeza.",
  str_homeland_secret_msg_10425 = "Aparentemente... ¡Las lágrimas de Pólux pueden convertirse en gemas!",
  str_homeland_secret_msg_10426 = "Pollux parece haber monopolizado muchos negocios clandestinos en Umbraton y ni siquiera se toma en serio al Señor de las Sombras.",
  str_homeland_secret_msg_10427 = "Pollux es bastante bueno con los niños.",
  str_homeland_secret_msg_10428 = "Escuché que Casta duerme con su rifle por la noche.",
  str_homeland_secret_msg_10429 = "A veces, Casta incluso duerme debajo de su cama.",
  str_homeland_secret_msg_10430 = "Casta parece haber tenido mucha suerte recientemente. Ha estado ganando juegos de adivinanzas casi siempre.",
  str_homeland_secret_msg_10431 = "Judge Jr. es en realidad un plebeyo. Por eso lleva tantos años sin ascender.",
  str_homeland_secret_msg_10432 = "Judge Jr. es una persona interpretada por varias personas que se turnan para ponerse una máscara haciéndose pasar por él.",
  str_homeland_secret_msg_10433 = "Judge Jr. en realidad no sabe cómo juzgar los casos. Él solo pierde el tiempo.",
  str_homeland_secret_msg_10434 = "¡Dicen que Lilica es famosa en Umbraton! ¡Vino aquí para alejarse de sus admiradores!",
  str_homeland_secret_msg_10435 = "Lilica parece haber comprado este dormitorio. ¡No olvides pagarle el alquiler!",
  str_homeland_secret_msg_10436 = "Lilica vino aquí con la intención de filmar un documental sobre el amor y el odio que se gesta en este lugar...",
  str_homeland_secret_msg_10437 = "Lilica en realidad odia actuar; ella solo lo hace por consideración a sus fans.",
  str_homeland_secret_msg_10438 = "Dicen que Minos estuvo en una pandilla durante sus días en Umbraton. Mejor quedarse en su lado bueno...",
  str_homeland_secret_msg_10439 = "Minos está criando en secreto una vaca en algún lugar del dormitorio. Eso explicaría los mugidos ocasionales en la noche...",
  str_homeland_secret_msg_10440 = "Minos parece ser muy aficionado a las historias de fantasmas.",
  str_homeland_secret_msg_10441 = "A pesar de que Minos es realmente fuerte, ¡en realidad le aterrorizan los insectos! Debe ser por eso que limpia todo tan meticulosamente.",
  str_homeland_secret_msg_10442 = "Sadie puede ser pequeña, ¡pero en realidad es increíblemente poderosa! ¡Ella puede recoger toda la casa!",
  str_homeland_secret_msg_10443 = "Sadie dice que sueña con convertirse en una jugadora de béisbol estrella y que vino a Cloud Gardens para buscar un lugar para construir un campo de béisbol.",
  str_homeland_secret_msg_10444 = "¡Sadie tiene un apetito loco! Puede comer cien trozos de bistec sin sudar, ¡no necesita verduras!",
  str_homeland_secret_msg_10445 = "En realidad, Axelia no puede hablar. Todos estos son mensajes pregrabados.",
  str_homeland_secret_msg_10446 = "Axelia parece joven, pero es una funcionaria de alto rango en la Federación Illumina.",
  str_homeland_secret_msg_10447 = "En realidad, Axelia le tiene miedo a los insectos.",
  str_homeland_secret_msg_10448 = "Noté que la cama de Axelia se derrumbó debajo de ella hace unos días. ¿Podría ser realmente pesada?",
  str_homeland_secret_msg_10449 = "¡Escuché que Beretta es bastante salvaje en la batalla!",
  str_homeland_secret_msg_10450 = "¡Aparentemente, Beretta es el maestro de Raphael!",
  str_homeland_secret_msg_10451 = "Las dos lanzas de Beretta pueden moverse solas, ¡así que no te acerques a ella por la noche!",
  str_homeland_secret_msg_10452 = "¡Goldie parece odiar todas las cosas amargas!",
  str_homeland_secret_msg_10453 = "El perro de Goldie también es una gran estrella. ¡Protagonizó un comercial antes!",
  str_homeland_secret_msg_10454 = "¡Escuché a Goldie gritar una vez! Creo que se estaba probando algo demasiado ajustado...",
  str_homeland_secret_msg_10455 = "No le pongas el lado malo a Goldie... Aunque parece una ídolo angelical, puede ser muy violenta.",
  str_homeland_secret_msg_10456 = "Vic puede parecer joven, pero en realidad es un viejo vejestorio...",
  str_homeland_secret_msg_10457 = "La última vez que vi a Vic dormirse, lloró con ese animalito peludo en sus brazos, diciendo: \"Ya no puedo comer...\"",
  str_homeland_secret_msg_10458 = "Puedes escuchar el canto de los pájaros en la habitación de Vic durante toda la noche. Es para dormir por aquí.",
  str_homeland_secret_msg_10459 = "¡Vic no es un gran bebedor! Sus maravillosas bestias suelen beber todo el alcohol que guarda.",
  str_homeland_secret_msg_10460 = "¡Brandy ganó una vez el Torneo de Lucha de Brazos de Umbraton! ¡Ella es tan fuerte!",
  str_homeland_secret_msg_10461 = "Incluso los Chubb han empezado a chismear desde que llegó Brandy.",
  str_homeland_secret_msg_10462 = "Los chismes que Brandy siempre dice pueden ser ciertos. Después de todo, ella es una chica honesta.",
  str_homeland_secret_msg_10463 = "¡Escuché que la familia de Zhong Xu se convirtió en gatos!",
  str_homeland_secret_msg_10464 = "¡La silla de ruedas de Zhong Xu supuestamente puede volar!",
  str_homeland_secret_msg_10465 = "Zhong Xu parece no tener sentido de la orientación. Siempre está buscando una \"brújula\".",
  str_homeland_secret_msg_10466 = "Zhong Xu no puede luchar para salvar su vida. Solía ser funcionario, por eso tiene tantas cositas de artesanía cultural.",
  str_homeland_secret_msg_10467 = "Yuebai supuestamente no puede nadar, entonces, ¿cómo se convirtió en capitana de un barco?",
  str_homeland_secret_msg_10468 = "Siento que cada vez que Yuebai sonríe, algo malo está por suceder...",
  str_homeland_secret_msg_10469 = "¡El apellido de Yuebai solía ser Sen!",
  str_homeland_secret_msg_10470 = "Yuebai usa una armadura de malla completa todo el tiempo, ¡como si pensara que alguien intentaría asesinarla en la noche!",
  str_homeland_secret_msg_10471 = "¡Escuché que Liqing podía comer cualquier cosa! Particularmente ama todo tipo de pasto... ¡Tal vez fue una cabra en una vida pasada!",
  str_homeland_secret_msg_10472 = "En realidad, la medicina de Liqing se prepara de acuerdo con las enseñanzas médicas de su maestro. No se le ha ocurrido ninguna idea.",
  str_homeland_secret_msg_10473 = "¡Liqing aparentemente tiene un gato como hermano!",
  str_homeland_secret_msg_10474 = "¡Nemesis ganó el concurso de rap de Illumina!",
  str_homeland_secret_msg_10475 = "¡Némesis aprendió a teletransportarse gracias a los miembros del Sindicato de Mensajeros!",
  str_homeland_secret_msg_10476 = "Resulta que todo el licor que Siobhan ha estado bebiendo es sin alcohol, pero se emborracha de todos modos. Qué puedo decir...",
  str_homeland_secret_msg_10477 = "Siobhan vino a Cloud Gardens para excavar estatuas de colosos supuestamente enterradas por los Caelestites.",
  str_homeland_secret_msg_10478 = "¡Aparentemente, Siobhan solía ser una estrella de cine en Umbraton!",
  str_homeland_secret_msg_10479 = "Jeriah duerme con su serpiente por la noche... ¡Qué terror!",
  str_homeland_secret_msg_10480 = "¡Se rumorea que Jeriah es la princesa de una tribu del desierto!",
  str_homeland_secret_msg_10481 = "Desde que Jeriah llegó aquí, los dormitorios se han vuelto mucho más animados recientemente con los gritos de todo tipo de animales...",
  str_homeland_secret_msg_10482 = "Jeriah parece ser vegetariano...",
  str_homeland_secret_msg_10483 = "¡Kya parece tener una memoria fotográfica! ¡Impresionante!",
  str_homeland_secret_msg_10484 = "Aunque Kya parece poco confiable, de hecho, ¡en realidad es muy madura! ¿Por qué otra razón sería tan buena en su trabajo?",
  str_homeland_secret_msg_10485 = "Kya odia el frío, por eso siempre está entregando cartas.",
  str_homeland_secret_msg_10486 = "¿Es cierto que Cuscuta trae buena suerte con ella donde quiera que vaya?",
  str_homeland_secret_msg_10487 = "Cuscuta en realidad tiene insomnio. Sus ojos están muy abiertos incluso cuando está dormida.",
  str_homeland_secret_msg_10488 = "¡La pistola de agua de Fia no está llena de agua sino de algo que puede congelarte instantáneamente!",
  str_homeland_secret_msg_10489 = "Fia en realidad tiene una voz muy hermosa. Muchas personas no pueden olvidarlo después de escucharla hablar.",
  str_homeland_secret_msg_10490 = "Fia a veces hace sonidos \"Lo... Lo\". ¿Está ella enferma?",
  str_homeland_secret_msg_10491 = "La somnolencia de Tina es falsa. La verdad es que tiene insomnio...",
  str_homeland_secret_msg_10492 = "El sonido de los ronquidos ha llenado el dormitorio desde entonces. Tina mudarse.",
  str_homeland_secret_msg_10493 = "Parece que las cosas buenas suceden cada vez que Tina abre los ojos",
  str_homeland_secret_msg_10494 = "Tina una vez viajé con un Eclipsite!",
  str_homeland_secret_msg_10495 = "Mira el arma mecánica de Leyn. Escuché que Illumina lo hizo para él.",
  str_homeland_secret_msg_10496 = "Leyn tiene un hermano perdido hace mucho tiempo que parece estar en Rediesel Desert.",
  str_homeland_secret_msg_10497 = "Yo vi Leyn con unos compañeros de Rediesel Wrench hace unos días. ¿Está pensando en desertar a ellos?",
  str_homeland_secret_msg_10498 = "Leyn Ha hablado en sueños un par de veces. Parece que realmente quiere una familia.",
  str_homeland_secret_msg_10499 = "La verdad es, Matthieu no sabe cómo tratar los casos!",
  str_homeland_secret_msg_10500 = "Desde Matthieu se mudó, alguien parece estar limpiando el dormitorio todos los días. Las habitaciones están tan limpias ahora.",
  str_homeland_secret_msg_10501 = "Escuché que la familia de Matthieu tiene un negocio de joyería.",
  str_homeland_secret_msg_10502 = "De hecho, Hati le encanta coleccionar muñecas, y puede estar seguro de que se pueden encontrar muchas en su casa.",
  str_homeland_secret_msg_10503 = "Hati tiene una inteligencia súper alta, y no hay crucigrama que no pueda resolver.",
  str_homeland_secret_msg_10504 = "parece como si Hati fue criado por una especie de bestia extraña...?",
  str_homeland_secret_msg_10505 = "Hati es muy bueno cocinando! ¡Su especialidad es el guiso de carne!",
  str_homeland_secret_msg_10506 = "Desde Kristen se mudó, ¡ha pedido a todos que doblen sus edredones en un cuadrado!",
  str_homeland_secret_msg_10507 = "Kristen una vez practicó con su lanza en su habitación, hasta que terminó haciendo un agujero en el techo...",
  str_homeland_secret_msg_10508 = "¡El sueño de Kristen es ser la heroína de un espectáculo de ópera!",
  str_homeland_secret_msg_10509 = "No te dejes engañar porque Yingel le gusta disparar desde la distancia. En realidad es miope.",
  str_homeland_secret_msg_10510 = "Yingel bebí demasiado de cierta leche hace unos días y tuve hipo toda la noche.",
  str_homeland_secret_msg_10511 = "Parece que Yingel se enfermará después de beber agua con gas, ¡así que tenga cuidado!",
  str_homeland_secret_msg_10512 = "Algún tipo de pájaro parece haber construido un nido por aquí desde entonces. Yingel mudarse.",
  str_homeland_secret_msg_10513 = "¡Impactante! Leo ¿realmente le gusta comer carne cruda?",
  str_homeland_secret_msg_10514 = "Parece que Leo trae una bañera cada vez que pelea.",
  str_homeland_secret_msg_10515 = "Parece que Leo puede dibujar mapas en su cabeza.",
  str_homeland_secret_msg_10516 = "Se dice que la ambición de Leo es convertirse en el nuevo Señor de la Ciudad de Lumopolis.",
  str_homeland_secret_msg_10517 = "No te metas en el lado malo de Anatoli. Lo anotará en su cuaderno y encontrará la oportunidad de vengarse.",
  str_homeland_secret_msg_10518 = "Anatoli tiene una excelente visión, puede ver las cosas claramente desde muy lejos, y puede leer los labios...",
  str_homeland_secret_msg_10519 = "No llames la atención de Anatoli, o hará todo lo posible para observarte...",
  str_homeland_secret_msg_10520 = "¿De verdad vive aquí? Ni siquiera lo he visto mucho por aquí...",
  str_homeland_secret_msg_10521 = "¡Ese tipo parece volverse más joven que antes!",
  str_homeland_secret_msg_10522 = "Escuché que el Schwartz ¡La familia tiene una técnica secreta para mantenerse siempre joven! ¡No es de extrañar que hayan logrado gobernar Lumopolis durante tanto tiempo!",
  str_homeland_secret_msg_10523 = "¡Se ha vuelto tan poderosa recientemente! ¿Se ha estado escabullendo a algún lugar para practicar?",
  str_homeland_secret_msg_10524 = "Después de que ella llegó, ¿fue mi imaginación o su habitación estaba llena de olor a té...?",
  str_homeland_secret_msg_10525 = "¡Una princesa de Lumopolis acaba de mudarse!",
  str_homeland_secret_msg_10526 = "¡Ay! Parece que tenemos una plaga de arañas... ¡Y es grande!",
  str_homeland_secret_msg_10527 = "Siento como si siguiera escuchando a alguien llamando \"Carleen, Carleen\" ¿tarde en la noche?",
  str_homeland_secret_msg_10528 = "Desde Jakine de Northland se mudó, he notado frecuentes destellos de luz en los dormitorios.",
  str_homeland_secret_msg_10529 = "¡Serpiente! Jakine trajo una serpiente aquí!",
  str_homeland_secret_msg_10530 = "Jakine no duerme por la noche! ¡Ella solo quiere estar de fiesta todo el tiempo!",
  str_homeland_secret_msg_20001 = "{1} y {2} tienen estilos de vida y hábitos muy diferentes. Pronto se llevará a cabo un nuevo \"Illumina vs. Lumopolis\" en el dormitorio, recuerda mis palabras.",
  str_homeland_secret_msg_20002 = "{1} quería abrir las ventanas, y {2} quería que se cerraran. Así que siguieron abriendo y cerrando las ventanas toda la noche...",
  str_homeland_secret_msg_20003 = "Ya que {1} mudarse, {2}Ha estado escuchando ruidos extraños, y ahora quiere mudarse...",
  str_homeland_secret_msg_20004 = "Ahora que ambos {1} y {2} se mudó, incluso el aire se siente sofisticado. ¡Oh, pero no soy fan de ellos!",
  str_homeland_secret_msg_20005 = "no dejes {1} y {2} vivir juntos. escuché eso {1} fue engañado por {2} en el pasado, por lo que definitivamente se pelearán. Esperar. No. ¡Las peleas ya comenzaron ayer!",
  str_homeland_secret_msg_20006 = "{1} le encanta pasar tiempo con {2}! No es que me gusten \"ellos\", pero me gusta el aire acondicionado natural que hacen...",
  str_homeland_secret_msg_20007 = "Cualquiera aquí que viva con {1} y {2}? Es tan silencioso que puedes escuchar el más mínimo sonido...",
  str_homeland_secret_msg_30001 = "Con {1} y {2} alrededor, incluso el dormitorio se siente como un campamento militar... Simplemente no dejan de hablar sobre estrategias y tácticas.",
  str_homeland_secret_msg_30002 = "{1} dijo que uno debe enfrentar la \"verdad\" mientras {2} dicho \"ser real\". Pensé que estaban teniendo una discusión filosófica, pero resultó que estaban discutiendo qué cenar.",
  str_homeland_secret_msg_30003 = "¿Alguien entiende lo que {1} y {2} ¿hablemos acerca? Sé cada palabra que dicen, pero no tengo la menor idea de lo que significan... ¿Es este el rumoreado \"lenguaje Umbratón\"?",
  str_homeland_secret_msg_30004 = "\"¡Pajarito!\" {1} parece amar {2}'s plumas. ¿Será porque eso {1} tambien es un animal? Hmm... ¡Debe ser así!",
  str_homeland_secret_msg_30005 = "Por lo que sé, {1} y {2} romper muchas tazas. 51, justo ayer. ¿Es así como practican el tiro?",
  str_homeland_secret_msg_30006 = "escuché eso {2} comió toda la comida {1} cocinado antes de que pudiera ser emplatado...",
  str_homeland_secret_msg_30007 = "Escuché llamadas extrañas hace unas noches. En primer lugar, {2} Pensé que eran las mascotas, pero luego resultó ser {1}... Quiero decir, ¿mascotas? Ja ja...",
  str_homeland_secret_msg_30008 = "Puedes sentir que el aire se endurece tan pronto como {1} y {2} están en la habitación. ¿Alguien ha tenido esa experiencia?",
  str_homeland_secret_msg_30009 = "Hace unos días, {2} mostró algunas habilidades. {1} no dijo nada, pero cuando regresé al dormitorio, escuché {1} murmurando algo sobre \"Illumina seguro que es impresionante\".",
  str_homeland_secret_msg_30010 = "{1} siempre dice {2} no entiende de música, pero eso también es lo que {2} dice sobre {1}... Que par.",
  str_homeland_secret_msg_30011 = "Últimamente, {2} a menudo tiene largas conversaciones con {1}. ¡Escuché que pronto saldrá un nuevo libro!",
  str_homeland_secret_msg_30012 = "{2} parece necesitar volver al Lejano Oriente, y {1} se va a acompañar.",
  str_homeland_secret_msg_30013 = "alguien ha estado siguiendo {1} y tomando fotografías. {2} está tratando de averiguarlo... ¿Quién podría ser?",
  str_homeland_secret_msg_30014 = "{1} y {2} parece haber encontrado algo de gran valor. Han estado viajando sin preocuparse por el mundo últimamente.",
  str_homeland_secret_msg_30015 = "{2} parece haber atrapado lo que sea {1}Tiene hace unos días. Espero que no se convierta en una pandemia aquí...",
  str_homeland_secret_msg_30016 = "{1} contó una historia sobre cómo \"{2} se apoderó de este lugar y lo gobernó\" mientras soñaba.",
  str_homeland_secret_msg_30017 = "escuché eso {1} tomó prestado algo de Nightium de {2} pero nunca lo devolvió. Como resultado, a menudo se puede escuchar que algo se afila por aquí.",
  str_homeland_secret_msg_30018 = "Algunos dicen que fue {1} y {2} quien en secreto parchó los agujeros en el techo del dormitorio.",
  str_homeland_secret_msg_30019 = "{1} y {2} parecen sonámbulos. Salieron unas cuantas noches.",
  str_homeland_secret_msg_30020 = "{1} parece haber ganado algo de peso mientras {2} perdido algunos. La transferencia de peso es una cosa ahora.",
  str_homeland_secret_msg_30021 = "{1} y {2} a menudo se peleaba por las luciérnagas por alguna razón.",
  str_homeland_secret_msg_30022 = "Yo vi {1} y {2} revisando el diario del Navegante en secreto. ¡Deben estar planeando algo contra el Navegante!",
  str_homeland_secret_msg_30023 = "escuché eso {1} y {2} hizo una apuesta en el lado del dormitorio con una mejor vista."
}
return config
